import Modal from 'flarum/common/components/Modal';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
import { t } from '../utils/settings';
import { getCommunityMore, setCommunityMore } from '../utils/sidebarPrefs';
/**
 * 侧栏主区域中哪些条目保持可见；未勾选的条目会进入
 * “更多”，如同 Discourse 的“自定义区域”。
 */
export default class CommunityCustomizeModal extends Modal {
  hidden = new Set();
  oninit(vnode) {
    super.oninit(vnode);
    this.hidden = new Set(getCommunityMore());
  }
  className() {
    return 'LcoySidebarCustomize Modal--small';
  }
  title() {
    return t('sidebar.customize_community');
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m("p", {
      className: "helpText"
    }, t('sidebar.customize_community_help')), m("ul", {
      className: "LcoySidebarCustomize-list"
    }, this.attrs.entries.map(entry => m("li", null, m("label", {
      className: "checkbox"
    }, m("input", {
      type: "checkbox",
      checked: !this.hidden.has(entry.key),
      onchange: () => this.toggle(entry.key)
    }), entry.icon && m(Icon, {
      name: entry.icon
    }), m("span", null, entry.label))))), m("div", {
      className: "LcoySidebarCustomize-actions"
    }, m(Button, {
      className: "Button Button--primary",
      onclick: () => this.save()
    }, t('sidebar.customize_save')), m(Button, {
      className: "Button Button--link",
      onclick: () => this.reset()
    }, t('sidebar.customize_reset'))));
  }
  toggle(key) {
    if (this.hidden.has(key)) this.hidden.delete(key);else this.hidden.add(key);
  }
  save() {
    setCommunityMore(Array.from(this.hidden));
    this.attrs.onsave?.();
    this.hide();
  }
  reset() {
    setCommunityMore([]);
    this.attrs.onsave?.();
    this.hide();
  }
}
flarum.reg.add('lcoy-roselle', 'forum/components/CommunityCustomizeModal', CommunityCustomizeModal);